def admit_reservations(capacity, requests):
    approved = []
    decisions = []
    for time, size, expires in requests:
        occupied = sum(amount for amount, deadline in approved if deadline > time)
        accepted = occupied + size <= capacity
        decisions.append(accepted)
        if accepted:
            approved.append((size, expires))
    return decisions

def logical_block_coverage(blocks, start, count):
    offset = 0
    coverage = []
    for kind, length in blocks:
        if kind == 'data':
            end = offset + length
            coverage.append(max(0, min(end, start + count) - max(offset, start)))
            offset = end
    return coverage

