def transaction_totals(events):
    active = {}
    committed = []
    for operation, transaction, amount in events:
        if operation == 'begin':
            active[transaction] = 0
        elif operation == 'add':
            active[transaction] += amount
        elif operation == 'commit':
            committed.append([transaction, active.pop(transaction)])
        else:
            active.pop(transaction)
    return committed

def transaction_totals(events):
    committed = []
    for beginning, (operation, transaction, amount) in enumerate(events):
        if operation != 'begin':
            continue
        for ending in range(beginning + 1, len(events)):
            terminal, owner, ignored_amount = events[ending]
            if owner == transaction and terminal in ('commit', 'rollback'):
                if terminal == 'commit':
                    total = sum(value for action, identity, value in events[beginning + 1:ending] if identity == transaction and action == 'add')
                    committed.append((ending, transaction, total))
                break
    return [[transaction, total] for ending, transaction, total in sorted(committed)]

