def sequence_gaps(events):
    highest = {}
    gaps = []
    for operation, key, number in events:
        if operation == 'reset':
            highest.pop(key, None)
            gaps.append(0)
        elif key not in highest:
            highest[key] = number
            gaps.append(0)
        elif number > highest[key]:
            gaps.append(number - highest[key] - 1)
            highest[key] = number
        else:
            gaps.append(0)
    return gaps

