def group_peaks(tokens):
    peaks = []
    current = 0
    peak = None
    seen_data = False
    for token in tokens:
        if token == -1000:
            peaks.append(peak if seen_data else None)
            current = 0
            peak = None
            seen_data = False
        elif token == -999:
            current = 0
        else:
            current += token
            if not seen_data or current > peak:
                peak = current
            seen_data = True
    peaks.append(peak if seen_data else None)
    return peaks

def group_peaks(tokens):
    groups = [[[]]]
    for token in tokens:
        if token == -1000:
            groups.append([[]])
        elif token == -999:
            groups[-1].append([])
        else:
            groups[-1][-1].append(token)
    return [max((sum(segment[:length]) for segment in group for length in range(1, len(segment) + 1)), default=None) for group in groups]

