def fulfill_orders(stock, orders):
    available = {}
    for label in stock:
        available[label] = available.get(label, 0) + 1
    decisions = []
    for order in orders:
        needed = {}
        for label in order:
            needed[label] = needed.get(label, 0) + 1
        accepted = all(available.get(label, 0) >= amount for label, amount in needed.items())
        decisions.append(accepted)
        if accepted:
            for label, amount in needed.items():
                available[label] -= amount
    return decisions

def fulfill_orders(stock, orders):
    available = list(stock)
    decisions = []
    for order in orders:
        trial = list(available)
        for label in order:
            if label not in trial:
                decisions.append(False)
                break
            trial.remove(label)
        else:
            available = trial
            decisions.append(True)
    return decisions

