def recency_evictions(capacity, updates):
    keys = []
    evicted = []
    for key, value in updates:
        if key in keys:
            keys.remove(key)
        keys.append(key)
        if len(keys) > capacity:
            evicted.append(keys.pop(0))
        else:
            evicted.append(None)
    return {'evicted': evicted, 'keys': keys}

def recency_evictions(capacity, updates):
    last_seen = {}
    evicted = []
    for position, (key, value) in enumerate(updates):
        last_seen[key] = position
        removed = None
        if len(last_seen) > capacity:
            removed = min(last_seen, key=last_seen.get)
            del last_seen[removed]
        evicted.append(removed)
    return {'evicted': evicted, 'keys': sorted(last_seen, key=last_seen.get)}

