def quota_selection(records, quotas):
    remaining = dict(quotas)
    ranked = sorted(range(len(records)), key=lambda index: (records[index][2], index))
    selected = []
    for index in ranked:
        category = records[index][1]
        if remaining.get(category, 0) > 0:
            selected.append(index)
            remaining[category] -= 1
    return sorted(selected)

def quota_selection(records, quotas):
    selected = []
    for category, limit in quotas:
        ranked = sorted((priority, position) for position, (label, owner, priority) in enumerate(records) if owner == category)
        selected.extend(position for priority, position in ranked[:limit])
    return sorted(selected)

